definition.script:
pipeline {
  agent any

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '10', artifactNumToKeepStr: '3'))
    timeout(time: 150, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  environment {
    NEXUS_REGISTRY = 'localhost:5001'
    SLUG = 'johndoe6345789/businessplanner'
  }

  stages {
    stage('Checkout') {
      steps {
        git branch: 'main', url: 'https://github.com/johndoe6345789/businessplanner.git'
      }
    }

    stage('Registry login') {
      steps {
        // :5001 packagerepo registry requires auth on push; create the
        // 'packagerepo-registry' Jenkins credential (user with push scope).
        withCredentials([usernamePassword(credentialsId: 'packagerepo-registry', usernameVariable: 'REG_USER', passwordVariable: 'REG_PASS')]) {
          sh 'echo "$REG_PASS" | docker login "$NEXUS_REGISTRY" -u "$REG_USER" --password-stdin'
        }
      }
    }

    stage('Acquire disk lock') {
      steps {
        // Best-effort cross-job advisory lock for this shared, disk-constrained
        // host: only ONE base build (metabuilder OR businessplanner) may run at
        // a time, else peak disk blows. The inspect-then-create race is
        // acceptable (base builds are long, infrequent, orchestrator-serialized).
        // docker-housekeeping also skips its prune while this volume exists.
        sh '''
          if docker volume inspect mb-base-running >/dev/null 2>&1; then
            echo "another base build holds the mb-base-running lock -- aborting to protect disk" >&2
            exit 1
          fi
          docker volume create mb-base-running >/dev/null
          touch .mb_lock_owned
        '''
        sh 'docker builder prune -f --filter until=48h || true'
      }
    }

    // Disk-safe SERIAL pipeline. Order matters: businessplanner-base-apt is built first
    // and kept resident because businessplanner-base-conan builds FROM it (local). node
    // has no local dependents, so it is pruned immediately. base-apt is dropped
    // at the very end. Peak disk ~= base-apt + one dependent.
    stage('Build+Push+Prune base images') {
      options { timeout(time: 140, unit: 'MINUTES') }
      steps {
        sh '''
          docker version
        '''
        script {
          def bases = [
            [name: 'businessplanner-base-apt',   file: '.local/docker/businessplanner-base-apt.Dockerfile',   keep: '1', args: ''],
            [name: 'businessplanner-base-conan', file: '.local/docker/businessplanner-base-conan.Dockerfile', keep: '0', args: '--build-arg APT_IMAGE=localhost:5001/johndoe6345789/businessplanner/businessplanner-base-apt:latest'],
            [name: 'businessplanner-base-node',  file: '.local/docker/businessplanner-base-node.Dockerfile',  keep: '0', args: ''],
          ]
          for (b in bases) {
            stage("base: ${b.name}") {
              catchError(message: "base ${b.name} failed -- dependent apps fall back to the last-good base in Nexus", buildResult: 'UNSTABLE', stageResult: 'FAILURE') {
                withEnv(["BASE_NAME=${b.name}", "BASE_FILE=${b.file}", "BASE_ARGS=${b.args}", "KEEP_LOCAL=${b.keep}"]) {
                  sh '''
                    set -e
                    docker build -f "$BASE_FILE" $BASE_ARGS \
                      -t "$NEXUS_REGISTRY/$SLUG/$BASE_NAME:latest" .
                  '''
                  sh '''
                    set -e
                    python3 - <<'PY'
import os
import subprocess

registry = os.environ["NEXUS_REGISTRY"]
slug = os.environ["SLUG"]
name = os.environ["BASE_NAME"]
keep = os.environ.get("KEEP_LOCAL") == "1"
tag = subprocess.check_output(["git", "rev-parse", "--short", "HEAD"], text=True).strip()

local = registry + "/" + slug + "/" + name + ":latest"

for version in ("sha-" + tag, "latest"):
    target = registry + "/" + slug + "/" + name + ":" + version
    subprocess.check_call(["docker", "tag", local, target])
    subprocess.check_call(["docker", "push", target])
    if target != local:
        subprocess.run(["docker", "rmi", "-f", target], check=False)
print("Pushed " + slug + "/" + name + " (sha-" + tag + ", latest)")

if keep:
    print("Kept local " + local + " (local dependents build FROM it)")
else:
    repo = local.split(":")[0]
    listed = subprocess.run(["docker", "images", "--format", "{{.Repository}}:{{.Tag}}"], capture_output=True, text=True).stdout.splitlines()
    for ln in listed:
        if ln.split(":")[0] == repo:
            subprocess.run(["docker", "rmi", "-f", ln], check=False)
    subprocess.run(["docker", "builder", "prune", "-f", "--filter", "until=24h"], check=False)
    print("Pruned local " + repo + " (freed disk before next base)")
PY
                  '''
                }
              }
            }
          }
          stage('drop base-apt') {
            sh '''
              docker images --format '{{.Repository}}:{{.Tag}}' \
                | grep '/businessplanner-base-apt:' \
                | xargs -r docker rmi -f 2>/dev/null || true
              docker builder prune -f --filter until=24h || true
            '''
          }
        }
      }
    }
  }

  post {
    always {
      sh 'if [ -f .mb_lock_owned ]; then docker volume rm -f mb-base-running >/dev/null 2>&1 || true; echo "released mb-base-running lock"; fi'
      cleanWs()
    }
  }
}
